1	// Command relayproof is the 跨链消息与轻客户端验证服务 entry point.
2	package main
3	
4	import (
5		"fmt"
6		"os"
7	
8		"github.com/asdhoaiqqq/relayproof-bridge/relayproof"
9	)
10	
11	func main() {
12		command := "demo"
13		if len(os.Args) > 1 {
14			command = os.Args[1]
15		}
16		switch command {
17		case "demo":
18			runDemo()
19		case "normalize":
20			runNormalize()
21		case "version":
22			fmt.Println("relayproof 0.1.0")
23		case "help", "-h", "--help":
24			usage()
25		default:
26			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
27			usage()
28			os.Exit(2)
29		}
30	}
31	
32	func usage() {
33		fmt.Println("usage: relayproof [demo|normalize|version|help]")
34		fmt.Println()
35		fmt.Println("  demo       run the built-in verification demo (default with no arguments)")
36		fmt.Println("  normalize   read newline-delimited JSON logs from stdin and write")
37		fmt.Println("              normalized event results to stdout, one JSON object per line;")
38		fmt.Println("              exits non-zero when one or more input lines fail")
39		fmt.Println("  version     print the relayproof version")
40		fmt.Println("  help        show this help")
