3	// End-to-end regression coverage for the normalize subcommand as users
4	// actually invoke it: logs arrive on stdin, per-line JSON results leave on
5	// stdout, diagnostics leave on stderr, and the exit status summarizes the
6	// run. These tests execute the real compiled binary so the relationship
7	// between per-line results, error output, and the process exit code is
8	// pinned exactly as the shell observes it. Everything runs locally with
9	// scripted input, so the checks are offline and deterministic.
10	
11	import (
12		"bytes"
13		"encoding/json"
14		"fmt"
15		"io"
16		"os"
17		"os/exec"
18		"path/filepath"
19		"strings"
20		"testing"
21		"unicode/utf16"
22		"unicode/utf8"
23	)
24	
25	// escKey renders key as a JSON member name spelled entirely with unicode
26	// escapes (with UTF-16 surrogate pairs above the BMP), so tests can feed a
27	// \uXXXX-encoded key without embedding escape text in the source.
28	func escKey(key string) string {
29		var b strings.Builder
30		b.WriteByte('"')
31		for _, r := range key {
32			for _, u := range utf16.Encode([]rune{r}) {
33				fmt.Fprintf(&b, "\\u%04x", u)
34			}
35		}
36		b.WriteByte('"')
37		return b.String()
38	}
39	
40	// normalizeBin is the compiled relayproof binary shared by all tests in
41	// this package, built once from the current sources.
42	var normalizeBin string
43	
44	func TestMain(m *testing.M) {
45		dir, err := os.MkdirTemp("", "relayproof-cli-test")
46		if err != nil {
47			panic(err)
48		}
49		defer os.RemoveAll(dir)
50	
51		normalizeBin = filepath.Join(dir, "relayproof")
52		build := exec.Command("go", "build", "-o", normalizeBin, ".")
53		if out, err := build.CombinedOutput(); err != nil {
54			panic("building relayproof for CLI tests: " + err.Error() + "\n" + string(out))
55		}
56		os.Exit(m.Run())
57	}
58	
59	// cliResult captures everything the surrounding shell can observe from one
60	// normalize invocation.
61	type cliResult struct {
62		stdout   string
63		stderr   string
64		exitCode int
65	}
66	
67	// runNormalizeCLI executes `relayproof normalize` with stdin fed from r and
68	// records stdout, stderr, and the exit code. A process that cannot be
69	// started at all fails the test rather than masquerading as an exit status.
70	func runNormalizeCLI(t *testing.T, stdin io.Reader) cliResult {
71		t.Helper()
72		cmd := exec.Command(normalizeBin, "normalize")
73		cmd.Stdin = stdin
74		var stdout, stderr bytes.Buffer
75		cmd.Stdout = &stdout
76		cmd.Stderr = &stderr
77	
78		err := cmd.Run()
79		result := cliResult{stdout: stdout.String(), stderr: stderr.String()}
80		switch {
81		case err == nil:
82			result.exitCode = 0
83		default:
84			exitErr, ok := err.(*exec.ExitError)
85			if !ok {
86				t.Fatalf("normalize process could not run: %v", err)
87			}
88			result.exitCode = exitErr.ExitCode()
89		}
90		return result
91	}
92	
93	// decodeStdoutResults parses stdout as newline-delimited JSON result
94	// objects. Any line that is not a JSON object — help text, a plain-text
95	// notice, a log fragment — fails the test, because stdout must carry
96	// machine-readable results and nothing else.
97	func decodeStdoutResults(t *testing.T, stdout string) []map[string]any {
98		t.Helper()
99		var results []map[string]any
100		decoder := json.NewDecoder(strings.NewReader(stdout))
101		for {
102			var record map[string]any
103			if err := decoder.Decode(&record); err != nil {
104				if err == io.EOF {
105					return results
106				}
107				t.Fatalf("stdout must contain only JSON result objects, got decode error %v after %d records: %q",
108					err, len(results), stdout)
109			}
110			results = append(results, record)
111		}
112	}
113	
114	// eventOf extracts the event object of a successful result.
115	func eventOf(t *testing.T, result map[string]any) map[string]any {
116		t.Helper()
117		event, ok := result["event"].(map[string]any)
118		if !ok {
119			t.Fatalf("result has no event object: %#v", result)
120		}
121		return event
122	}
123	
124	// A healthy run: every log line normalizes, stdout carries one JSON result
125	// per line and nothing else, stderr stays silent, and the process exits 0.
126	// Alias keys must surface under their canonical names, the timestamp must be
127	// converted to UTC, the action trimmed, and unmapped fields must survive in
128	// extra with their JSON types intact.
129	func TestNormalizeCLIAllValidExitsZero(t *testing.T) {
130		input := `{"time":"2026-01-02T08:04:05+08:00","src_ip":"2001:db8::1","event_type":"  login  ","user":" alice ","retries":2,"ok":true}` + "\n" +
131			`{"timestamp":"2026-01-02T00:00:00Z","action":"logout","source_ip":"10.0.0.9","tags":["a","b"],"meta":{"trace":"t-1"}}` + "\n"
132	
133		result := runNormalizeCLI(t, strings.NewReader(input))
134	
135		if result.exitCode != 0 {
136			t.Fatalf("all-valid input must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
137		}
138		if result.stderr != "" {
139			t.Fatalf("a clean run must not write to stderr, got %q", result.stderr)
140		}
141	
142		results := decodeStdoutResults(t, result.stdout)
143		if len(results) != 2 {
144			t.Fatalf("expected one result per input line, got %#v", results)
145		}
146	
147		first := results[0]
148		if first["line"] != float64(1) || first["ok"] != true {
149			t.Fatalf("first result must report line 1 as ok: %#v", first)
150		}
151		event := eventOf(t, first)
152		if event["timestamp"] != "2026-01-02T00:04:05Z" {
153			t.Fatalf("alias time must land in timestamp converted to UTC, got %v", event["timestamp"])
154		}
155		if event["source_ip"] != "2001:db8::1" {
156			t.Fatalf("alias src_ip must land in source_ip, got %v", event["source_ip"])
157		}
158		if event["action"] != "login" {
159			t.Fatalf("alias event_type must land in action with whitespace trimmed, got %v", event["action"])
160		}
161		extra, ok := event["extra"].(map[string]any)
162		if !ok {
163			t.Fatalf("unmapped fields must be kept in extra: %#v", event)
164		}
165		if extra["user"] != " alice " {
166			t.Fatalf("extra strings must pass through verbatim, got %v", extra["user"])
167		}
168		if extra["retries"] != float64(2) {
169			t.Fatalf("extra numbers must stay numbers, got %#v", extra["retries"])
170		}
171		if extra["ok"] != true {
172			t.Fatalf("extra booleans must stay booleans, got %#v", extra["ok"])
173		}
174	
175		second := results[1]
176		if second["line"] != float64(2) || second["ok"] != true {
177			t.Fatalf("second result must report line 2 as ok: %#v", second)
178		}
179		event = eventOf(t, second)
180		if event["action"] != "logout" || event["source_ip"] != "10.0.0.9" {
181			t.Fatalf("canonical fields must round-trip unchanged: %#v", event)
182		}
183		extra, ok = event["extra"].(map[string]any)
184		if !ok {
185			t.Fatalf("structured extra fields must be kept: %#v", event)
186		}
187		tags, ok := extra["tags"].([]any)
188		if !ok || len(tags) != 2 || tags[0] != "a" || tags[1] != "b" {
189			t.Fatalf("extra arrays must keep their element order and types, got %#v", extra["tags"])
190		}
191		meta, ok := extra["meta"].(map[string]any)
192		if !ok || meta["trace"] != "t-1" {
193			t.Fatalf("extra objects must survive the command entry intact, got %#v", extra["meta"])
194		}
195	}
196	
197	// The key mixed-input case: a field-invalid log between two valid ones. The
198	// bad line gets an ok:false result with an explanatory error and no event,
199	// the surrounding valid lines still succeed in input order, and the process
200	// exits 1 — it must neither stop at the first bad line nor let the trailing
201	// success reset the status to 0. stderr stays empty because the failure is
202	// described by its own result record.
203	func TestNormalizeCLIInvalidLineBetweenValidOnesExitsOne(t *testing.T) {
204		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
205			`{"timestamp":"not-a-time","action":"broken"}` + "\n" +
206			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n"
207	
208		result := runNormalizeCLI(t, strings.NewReader(input))
209	
210		if result.exitCode != 1 {
211			t.Fatalf("one invalid log must set exit status 1, got %d (stderr: %q)", result.exitCode, result.stderr)
212		}
213		if result.stderr != "" {
214			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
215		}
216	
217		results := decodeStdoutResults(t, result.stdout)
218		if len(results) != 3 {
219			t.Fatalf("processing must continue past the bad line; expected 3 results, got %#v", results)
220		}
221	
222		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
223			t.Fatalf("the leading valid log must succeed on line 1: %#v", results[0])
224		}
225		if eventOf(t, results[0])["action"] != "first" {
226			t.Fatalf("line 1 event content mismatch: %#v", results[0])
227		}
228	
229		bad := results[1]
230		if bad["line"] != float64(2) || bad["ok"] != false {
231			t.Fatalf("the invalid log must be reported as line 2 with ok=false: %#v", bad)
232		}
233		if _, exists := bad["event"]; exists {
234			t.Fatalf("a failed line must not carry an event: %#v", bad)
235		}
236		message, ok := bad["error"].(string)
237		if !ok || message == "" {
238			t.Fatalf("a failed line must explain itself in error: %#v", bad)
239		}
240		if !strings.Contains(message, "timestamp") {
241			t.Fatalf("the error must name the offending field, got %q", message)
242		}
243	
244		if results[2]["line"] != float64(3) || results[2]["ok"] != true {
245			t.Fatalf("the trailing valid log must still succeed on line 3: %#v", results[2])
246		}
247		if eventOf(t, results[2])["action"] != "last" {
248			t.Fatalf("line 3 event content mismatch: %#v", results[2])
249		}
250	}
251	
252	// Blank lines produce no results but still consume physical line numbers,
253	// and a final complete log without a trailing newline is processed like any
254	// other. The run is clean, so the exit status is 0 and stderr stays empty.
255	func TestNormalizeCLIBlankLinesAndMissingFinalNewline(t *testing.T) {
256		input := "\n" +
257			"   \n" +
258			`{"timestamp":"2026-01-02T00:00:00Z","action":"alpha"}` + "\n" +
259			"\t\n" +
260			`{"timestamp":"2026-01-02T00:00:01Z","action":"omega"}` // no trailing newline
261	
262		result := runNormalizeCLI(t, strings.NewReader(input))
263	
264		if result.exitCode != 0 {
265			t.Fatalf("blank lines and a newline-less tail must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
266		}
267		if result.stderr != "" {
268			t.Fatalf("a clean run must not write to stderr, got %q", result.stderr)
269		}
270	
271		results := decodeStdoutResults(t, result.stdout)
272		if len(results) != 2 {
273			t.Fatalf("blank lines must not produce results, got %#v", results)
274		}
275		if results[0]["line"] != float64(3) {
276			t.Fatalf("line numbers must count blank physical lines, got %#v", results[0])
277		}
278		if results[0]["ok"] != true || eventOf(t, results[0])["action"] != "alpha" {
279			t.Fatalf("line 3 result mismatch: %#v", results[0])
280		}
281		if results[1]["line"] != float64(5) {
282			t.Fatalf("the final log must keep its physical line number 5, got %#v", results[1])
283		}
284		if results[1]["ok"] != true || eventOf(t, results[1])["action"] != "omega" {
285			t.Fatalf("a final line without newline must normalize normally: %#v", results[1])
286		}
287	}
288	
289	// Empty input — and input holding only blank lines — ends quietly: no
290	// results, no diagnostics, exit status 0.
291	func TestNormalizeCLIEmptyOrBlankOnlyInput(t *testing.T) {
292		cases := []struct {
293			name  string
294			input string
295		}{
296			{"completely empty", ""},
297			{"only blank lines", "\n   \n\t\n"},
298		}
299		for _, tc := range cases {
300			t.Run(tc.name, func(t *testing.T) {
301				result := runNormalizeCLI(t, strings.NewReader(tc.input))
302				if result.exitCode != 0 {
303					t.Fatalf("input without logs must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
304				}
305				if result.stdout != "" {
306					t.Fatalf("no logs means no results on stdout, got %q", result.stdout)
307				}
308				if result.stderr != "" {
309					t.Fatalf("no logs means no diagnostics on stderr, got %q", result.stderr)
310				}
311			})
312		}
313	}
314	
315	// A stdin read failure before any complete log line is a stream-level
316	// problem, not a bad log: the process exits 2, stderr explains the read
317	// failure with the normalize: prefix, and stdout carries no per-line
318	// results — the failure must not be disguised as one log's field error.
319	func TestNormalizeCLIReadErrorExitsTwo(t *testing.T) {
320		// Reading a directory fails deterministically on the first Read, before
321		// any byte of a log line can arrive.
322		dir, err := os.Open(".")
323		if err != nil {
324			t.Fatalf("opening a directory as failing stdin: %v", err)
325		}
326		defer dir.Close()
327	
328		result := runNormalizeCLI(t, dir)
329	
330		if result.exitCode != 2 {
331			t.Fatalf("a stdin read failure must exit 2, got %d (stderr: %q)", result.exitCode, result.stderr)
332		}
333		if result.stdout != "" {
334			t.Fatalf("no complete log line means no results on stdout, got %q", result.stdout)
335		}
336		if !strings.HasPrefix(result.stderr, "normalize: ") {
337			t.Fatalf("the read failure must be reported with the normalize: prefix, got %q", result.stderr)
338		}
339		if !strings.Contains(strings.ToLower(result.stderr), "read") {
340			t.Fatalf("the diagnostic must identify a read failure, got %q", result.stderr)
341		}
342	}
343	
344	// A log line with corrupted characters — invalid UTF-8 bytes or an unpaired
345	// \uXXXX surrogate escape anywhere in the object, including deep inside
346	// unmapped fields — is an ordinary per-line failure: one ok:false record with
347	// the physical line number and a reason that distinguishes the two defects,
348	// no event, valid lines around it still processed in order, exit status 1,
349	// and stderr empty. The failure records themselves must be valid UTF-8 JSON:
350	// corrupted input bytes are never echoed back into the output.
351	func TestNormalizeCLICorruptedCharactersExitOne(t *testing.T) {
352		input := []byte(`{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
353			`{"timestamp":"2026-01-02T00:00:00Z","action":"bad` + "\xff\xfe" + `"}` + "\n" +
354			`{"timestamp":"2026-01-02T00:00:00Z","action":"ok","extra":{"deep":["` + "\\uD800" + `"]}}` + "\n" +
355			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n")
356	
357		result := runNormalizeCLI(t, bytes.NewReader(input))
358	
359		if result.exitCode != 1 {
360			t.Fatalf("corrupted log lines must set exit status 1, got %d (stderr: %q)", result.exitCode, result.stderr)
361		}
362		if result.stderr != "" {
363			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
364		}
365		if !utf8.ValidString(result.stdout) {
366			t.Fatalf("stdout must be valid UTF-8 even for corrupted input, got %q", result.stdout)
367		}
368	
369		results := decodeStdoutResults(t, result.stdout)
370		if len(results) != 4 {
371			t.Fatalf("processing must continue past corrupted lines; expected 4 results, got %#v", results)
372		}
373		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
374			t.Fatalf("the leading valid log must succeed on line 1: %#v", results[0])
375		}
376	
377		badUTF8 := results[1]
378		if badUTF8["line"] != float64(2) || badUTF8["ok"] != false {
379			t.Fatalf("the invalid-UTF-8 log must fail as line 2: %#v", badUTF8)
380		}
381		if _, exists := badUTF8["event"]; exists {
382			t.Fatalf("a corrupted line must not carry an event: %#v", badUTF8)
383		}
384		msg, _ := badUTF8["error"].(string)
385		if !strings.Contains(msg, "UTF-8") {
386			t.Fatalf("invalid bytes must be reported as UTF-8 corruption, got %q", msg)
387		}
388	
389		badEscape := results[2]
390		if badEscape["line"] != float64(3) || badEscape["ok"] != false {
391			t.Fatalf("the unpaired-escape log must fail as line 3: %#v", badEscape)
392		}
393		if _, exists := badEscape["event"]; exists {
394			t.Fatalf("a corrupted line must not carry an event: %#v", badEscape)
395		}
396		msg, _ = badEscape["error"].(string)
397		if !strings.Contains(msg, "surrogate") {
398			t.Fatalf("an unpaired escape deep in extra must be reported as a surrogate problem, got %q", msg)
399		}
400	
401		if results[3]["line"] != float64(4) || results[3]["ok"] != true {
402			t.Fatalf("the trailing valid log must still succeed on line 4: %#v", results[3])
403		}
404		if eventOf(t, results[3])["action"] != "last" {
405			t.Fatalf("line 4 event content mismatch: %#v", results[3])
406		}
407	}
408	
409	// A duplicate top-level key written with a unicode escape is the same failure
410	// as a literal repeated key. With one such line between legal logs (and a
411	// blank line shifting physical numbers), the CLI must emit per-line JSON
412	// results in order, keep the failure's line number with no event and a reason
413	// that names the field, and still exit 1: trailing valid lines never reset
414	// the status. An escape-only spelling of a standard field is a normal event.
415	func TestNormalizeCLIEscapedDuplicateKeyExitsOne(t *testing.T) {
416		dup := `{"timestamp":"2026-01-02T00:00:00Z","action":"first",` + escKey("action") + `:"second"}`
417		escapedOnly := `{` + escKey("timestamp") + `:"2026-01-02T08:04:05+08:00",` + escKey("action") + `:"ok"}`
418		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
419			dup + "\n" +
420			"  \n" +
421			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n" +
422			escapedOnly
423	
424		result := runNormalizeCLI(t, strings.NewReader(input))
425	
426		if result.exitCode != 1 {
427			t.Fatalf("a duplicate-key line must set exit status 1 even with later valid logs, got %d (stderr: %q)",
428				result.exitCode, result.stderr)
429		}
430		if result.stderr != "" {
431			t.Fatalf("per-line failures belong in result records, not stderr, got %q", result.stderr)
432		}
433	
434		results := decodeStdoutResults(t, result.stdout)
435		if len(results) != 4 {
