1	package relayproof
2	
3	// Regression coverage for source-address equivalence: an IPv4 address and
4	// its IPv4-mapped IPv6 spellings denote one source and must normalize and
5	// merge identically, while other IPv4-embedded IPv6 forms (the deprecated
6	// "IPv4-compatible" range) are distinct addresses that merge only with
7	// themselves and conflict with the mapped family. A value that merely
8	// resembles an address (e.g. carries a port) is invalid input and fails
9	// the whole line; it is never repaired and merged.
10	
11	import (
12		"strings"
13		"testing"
14	)
15	
16	// ipv4MappedSpellings are the accepted spellings of one and the same
17	// source: the plain IPv4 form, the dotted IPv4-mapped IPv6 form, and the
18	// hexadecimal IPv4-mapped form. All normalize to "192.0.2.1".
19	var ipv4MappedSpellings = []string{"192.0.2.1", "::ffff:192.0.2.1", "::FFFF:C000:0201"}
20	
21	// ipv4CompatibleSpellings are two spellings of the IPv4-compatible address
22	// ::c000:201. It embeds the same 32 bits as 192.0.2.1 but is a distinct
23	// IPv6 address, so it must never merge with the mapped family above.
24	var ipv4CompatibleSpellings = []string{"::192.0.2.1", "0:0:0:0:0:0:c000:201"}
25	
26	const (
27		validTS     = `"2026-01-02T00:00:00Z"`
28		validAction = `"login"`
29	)
30	
31	// TestNormalizeIPv4MappedSpellingsAlone pins the canonical form of the
32	// mapped family: provided on its own, under either the canonical name or
33	// the alias, every spelling yields source_ip 192.0.2.1.
34	func TestNormalizeIPv4MappedSpellingsAlone(t *testing.T) {
35		for _, field := range []string{FieldSourceIP, "src_ip"} {
36			for _, ip := range ipv4MappedSpellings {
37				input := `{"timestamp":` + validTS + `,"action":` + validAction + `,"` + field + `":"` + ip + `"}`
38				results := runNormalize(t, input)
39				if len(results) != 1 || results[0]["ok"] != true {
40					t.Fatalf("%s %q must succeed on its own: %#v", field, ip, results)
41				}
42				if results[0]["line"] != float64(1) {
